    --border-color: #3a3a4e;
    --success: #4ade80;
    --danger: #ff6b6b;
    --warning: #fbbf24;
    --spacing-unit: 1rem;
}

/* Global Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
}

a {
    color: var(--accent);
    text-decoration: none;
    transition: color 0.3s ease;
}

a:hover {
    color: var(--accent);
    opacity: 0.8;
}

button {
    cursor: pointer;
    transition: all 0.3s ease;
}

img {
    display: block;
    max-width: 100%;
    height: auto;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-unit);
}

/* Header & Navigation */
.header {
    background-color: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 1000;
}

.navbar {
    padding: 1rem 0;
}

.navbar-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-unit);
}

.logo h1 {
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: 0.15em;
    background: linear-gradient(135deg, var(--accent), var(--accent-dark));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: 2rem;
    flex: 1;
    justify-content: center;
}

.nav-menu a {
    font-size: 0.95rem;
    font-weight: 500;
    color: var(--text-secondary);
    transition: color 0.3s ease;
}

.nav-menu a:hover {
    color: var(--accent);
}

.nav-actions {
    display: flex;
    gap: 1rem;
}

.icon-btn {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    padding: 0.5rem;
    color: var(--text-secondary);
    transition: color 0.3s ease;
}

.icon-btn:hover {
    color: var(--accent);
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, var(--bg-secondary), var(--bg-tertiary));
    padding: 6rem var(--spacing-unit);
    text-align: center;
    border-bottom: 1px solid var(--border-color);
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
    background: linear-gradient(135deg, var(--accent), var(--accent-dark));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-content p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.cta-btn {
    background: linear-gradient(135deg, var(--accent), var(--accent-dark));
    color: var(--bg-primary);
    border: none;
    padding: 1rem 2.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 0.5rem;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.cta-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 16px rgba(201, 160, 220, 0.3);
}

/* Section Styling */
section {
    padding: 4rem var(--spacing-unit);
    border-bottom: 1px solid var(--border-color);
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2.2rem;
    font-weight: 700;
}

.view-all {
    color: var(--accent);
    font-weight: 600;
    transition: transform 0.3s ease;
}

.view-all:hover {
    transform: translateX(4px);
}

/* Featured Products Section */
.featured-section {
    background-color: var(--bg-primary);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    overflow: hidden;
    transition: all 0.3s ease;
}

.product-card:hover {
    border-color: var(--accent);
    box-shadow: 0 8px 24px rgba(201, 160, 220, 0.15);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    height: 200px;
    background-color: var(--bg-tertiary);
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    padding: 1.5rem;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.product-info .category {
    color: var(--text-secondary);
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

.product-info .price {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--accent);
    margin-bottom: 1rem;
}

.product-btn {
    width: 100%;
    background: linear-gradient(135deg, var(--accent), var(--accent-dark));
    color: var(--bg-primary);
    border: none;
    padding: 0.75rem;
    border-radius: 0.5rem;
    font-weight: 600;
    transition: all 0.3s ease;
}

.product-btn:hover {
    transform: scale(1.02);
    box-shadow: 0 4px 12px rgba(201, 160, 220, 0.3);
}

/* Deals Section */
.deals-section {
    background-color: var(--bg-primary);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.deal-card {
    background: linear-gradient(135deg, var(--bg-secondary), var(--bg-tertiary));
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    padding: 2rem;
    position: relative;
    transition: all 0.3s ease;
    overflow: hidden;
}

.deal-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(201, 160, 220, 0.1), transparent);
    opacity: 0;
    transition: opacity 0.3s ease;
}

.deal-card:hover::before {
    opacity: 1;
}

.deal-card.highlight {
    border-color: var(--accent);
    box-shadow: 0 0 24px rgba(201, 160, 220, 0.2);
}

.deal-card h3 {
    font-size: 1.3rem;
    margin-bottom: 0.75rem;
    position: relative;
    z-index: 1;
}

.deal-card p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    position: relative;
    z-index: 1;
}

.deal-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: var(--warning);
    color: var(--bg-primary);
    padding: 0.5rem 1rem;
    border-radius: 0.5rem;
    font-weight: 700;
    font-size: 0.95rem;
}

.deal-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    position: relative;
    z-index: 1;
}

.discount-price {
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--accent);
}

.deal-btn {
    background: var(--accent);
    color: var(--bg-primary);
    border: none;
    padding: 0.75rem 1.5rem;
    border-radius: 0.5rem;
    font-weight: 600;
    transition: all 0.3s ease;
}

.deal-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(201, 160, 220, 0.4);
}

/* Editorial Section */
.editorial-section {
    background-color: var(--bg-primary);
}

.editorial-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 2rem;
}

.editorial-card {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    overflow: hidden;
    transition: all 0.3s ease;
}

.editorial-card:hover {
    border-color: var(--accent);
    box-shadow: 0 8px 24px rgba(201, 160, 220, 0.15);
}

.featured-editorial {
    grid-column: 1;
    grid-row: 1 / 3;
}

.editorial-image {
    width: 100%;
    height: 250px;
    overflow: hidden;
    background-color: var(--bg-tertiary);
}

.featured-editorial .editorial-image {
    height: 100%;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-content {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
}

.article-category {
    color: var(--accent);
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.75rem;
}

.editorial-card h3 {
    font-size: 1.2rem;
    margin-bottom: 0.75rem;
    line-height: 1.4;
}

.featured-editorial h3 {
    font-size: 1.8rem;
}

.editorial-card p {
    color: var(--text-secondary);
    margin-bottom: 1rem;
    flex-grow: 1;
}

.editorial-card time {
    color: var(--accent-dark);
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

.read-more {
    color: var(--accent);
    font-weight: 600;
    display: inline-block;
    transition: transform 0.3s ease;
}

.read-more:hover {
    transform: translateX(4px);
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, var(--bg-secondary), var(--bg-tertiary));
    text-align: center;
    padding: 4rem var(--spacing-unit);
}

.newsletter-content h2 {
    font-size: 2rem;
    margin-bottom: 0.75rem;
}

.newsletter-content p {
    color: var(--text-secondary);
    margin-bottom: 2rem;
    font-size: 1.05rem;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
    max-width: 500px;
    margin: 0 auto;
    flex-wrap: wrap;
    justify-content: center;
}

.newsletter-form input {
    flex: 1;
    min-width: 200px;
    padding: 0.9rem 1.2rem;
    background-color: var(--bg-primary);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    border-radius: 0.5rem;
    transition: border-color 0.3s ease;
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent);
    box-shadow: 0 0 8px rgba(201, 160, 220, 0.2);
}

.newsletter-form input::placeholder {
    color: var(--text-secondary);
}

.newsletter-btn {
    background: var(--accent);
    color: var(--bg-primary);
    border: none;
    padding: 0.9rem 2rem;
    border-radius: 0.5rem;
    font-weight: 600;
    transition: all 0.3s ease;
}

.newsletter-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(201, 160, 220, 0.4);
}

/* Footer */
.footer {
    background-color: var(--bg-secondary);
    border-top: 1px solid var(--border-color);
    padding: 3rem var(--spacing-unit) 1rem;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-column h4 {
    font-size: 1rem;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

.footer-column ul {
    list-style: none;
}

.footer-column ul li {
    margin-bottom: 0.75rem;
}

.footer-column a {
    color: var(--text-secondary);
    transition: color 0.3s ease;
}

.footer-column a:hover {
    color: var(--accent);
}

.social-links {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
}

.footer-bottom {
    border-top: 1px solid var(--border-color);
    padding-top: 1rem;
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* Responsive Design */
@media (max-width: 768px) {
    .nav-menu {
        display: none;
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
        gap: 1rem;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .featured-editorial {
        grid-column: 1;
        grid-row: auto;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        min-width: 100%;
    }

    .footer-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 480px) {
    .navbar-content {
        flex-direction: column;
        gap: 1rem;
    }

    .logo h1 {
        font-size: 1.4rem;
    }

    .hero {
        padding: 3rem var(--spacing-unit);
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .section-header h2 {
        font-size: 1.5rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .product-image {
        height: 150px;
    }

    .deal-card {
        padding: 1.5rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

@media (prefers-color-scheme: light) {
    :root {
        --bg-primary: #ffffff;
        --bg-secondary: #f8f8fa;
        --bg-tertiary: #f0f0f5;
        --text-primary: #0f0f1e;
        --text-secondary: #5a5a70;
        --accent: #9d5fd0;
        --accent-dark: #7a4ba8;
        --border-color: #e0e0e8;
    }
}

/* Focus Styles for Accessibility */
button:focus-visible,
a:focus-visible,
input:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}
